/** M3: Q&A stage intake. The founder's answers to agent-generated questions, validated before an agent ever sees them. */

export interface QaQuestion {
  /** Stable id generated by the question step, e.g. "q1". */
  id: string;
  question: string;
  /** One sentence: why this answer changes the build. */
  why: string;
}

export interface QuestionSet {
  questions: QaQuestion[];
}

export interface QaAnswer {
  questionId: string;
  answer: string;
}

const MAX_ANSWER_LEN = 2000;

/**
 * Answers must reference real questions from the generated set, be non-empty
 * strings and stay bounded. Unknown or duplicate question ids are rejected:
 * an answer to a question nobody asked would silently distort the brief.
 */
export function validateAnswers(raw: unknown, set: QuestionSet): QaAnswer[] {
  if (!Array.isArray(raw)) throw new Error('answers must be an array');
  const known = new Map(set.questions.map((q) => [q.id, q]));
  const seen = new Set<string>();
  const out: QaAnswer[] = [];
  for (const item of raw) {
    if (typeof item !== 'object' || item === null) throw new Error('each answer must be an object');
    const a = item as Record<string, unknown>;
    if (typeof a.questionId !== 'string' || !known.has(a.questionId)) {
      throw new Error(`answer references unknown question id: ${String(a.questionId)}`);
    }
    if (seen.has(a.questionId)) throw new Error(`duplicate answer for question ${a.questionId}`);
    if (typeof a.answer !== 'string' || !a.answer.trim()) {
      throw new Error(`answer for ${a.questionId} must be a non-empty string`);
    }
    if (a.answer.length > MAX_ANSWER_LEN) {
      throw new Error(`answer for ${a.questionId} exceeds ${MAX_ANSWER_LEN} characters`);
    }
    seen.add(a.questionId);
    out.push({ questionId: a.questionId, answer: a.answer.trim() });
  }
  if (out.length === 0) throw new Error('at least one answer is required');
  return out;
}
